package com.parcelproof;
import jakarta.validation.constraints.*;import java.math.*;import java.time.*;
record ApiResponse<T>(boolean success,String message,T data){static <T> ApiResponse<T> ok(String m,T d){return new ApiResponse<>(true,m,d);}static <T> ApiResponse<T> fail(String m){return new ApiResponse<>(false,m,null);}}
record RegisterRequest(@NotBlank @Size(min=2) String fullName,@Email @NotBlank String email,@NotBlank @Size(min=8) String password,String phone,String address,UserRole role){} record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} record AuthResponse(String token,UserResponse user){} record UserResponse(Long id,String fullName,String email,String role,String phone,String address,String status,String vehicleNumber,String vehicleType,String availabilityStatus){}
record ParcelRequest(@NotBlank String senderName,@NotBlank String senderPhone,@NotBlank String senderAddress,@NotBlank String receiverName,@NotBlank String receiverPhone,@NotBlank String receiverAddress,@NotBlank String receiverCity,@NotNull ParcelType parcelType,@NotNull @DecimalMin("0.01") BigDecimal weight,@NotNull @DecimalMin("0.00") BigDecimal deliveryFee,@NotNull PaymentStatus paymentStatus,@NotNull ParcelPriority priority,Long customerId,LocalDate pickupDate,@NotNull LocalDate expectedDeliveryDate){}
record ParcelResponse(Long id,String trackingCode,String senderName,String senderPhone,String senderAddress,String receiverName,String receiverPhone,String receiverAddress,String receiverCity,String parcelType,BigDecimal weight,BigDecimal deliveryFee,String paymentStatus,String priority,String status,Long assignedDriverId,String assignedDriverName,Long customerId,String customerName,LocalDate pickupDate,LocalDate expectedDeliveryDate,LocalDateTime deliveredAt,Boolean otpVerified,String deliveryOtp,String proofNote,String proofPhotoPath,LocalDateTime createdAt){}
record PublicTrackingResponse(String trackingCode,String receiverName,String receiverCity,String parcelType,String priority,String status,LocalDate expectedDeliveryDate,Boolean delivered,Boolean proofVerified){} record AssignDriverRequest(@NotNull Long driverId){} record StatusUpdateRequest(@NotNull ParcelStatus status,String note){} record VerifyDeliveryRequest(@NotBlank @Pattern(regexp="^[0-9]{6}$") String otp,@Size(max=300) String proofNote,@Size(max=255) String proofPhotoPath){} record FailedAttemptRequest(@NotNull FailureReason failureReason,@Size(max=300) String notes,@Size(max=255) String proofPhotoPath){} record TimelineResponse(Long id,String status,String description,String updatedBy,String locationNote,Boolean publicVisible,LocalDateTime createdAt){}
